-- Restore the admin deposit control-plane RPC and expose deposit operations in the main admin UI.\n-- This is intentionally admin-only: the function checks the authenticated user's role.\n\ncreate or replace function public.admin_overview()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path='public','pg_temp'\nas $$\ndeclare result jsonb;\nbegin\n  if auth.uid() is null or not exists(select 1 from public.users where id=auth.uid() and role='admin') then\n    raise exception 'ADMIN_AUTHORIZATION_REQUIRED';\n  end if;\n\n  select jsonb_build_object(\n    'settings',(select to_jsonb(s) from public.system_settings s where s.id='00000000-0000-0000-0000-000000000001'),\n    'pending_deposits',(select count(*) from public.deposit_requests where status='pending'),\n    'recent_deposits',coalesce((\n      select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (\n        select d.id,d.user_id,d.amount,d.method,d.status,d.reference,d.payment_reference,d.user_note,d.admin_note,d.created_at,d.processed_at,\n               u.full_name,u.email,\n               coalesce((t.metadata->>'investment_intent')::boolean,false) as investment_intent,\n               nullif(t.metadata->>'strategy_id','')::uuid as strategy_id,\n               st.name as strategy_name\n        from public.deposit_requests d\n        left join public.users u on u.id=d.user_id\n        left join lateral (select tx.metadata from public.transactions tx where tx.reference=d.reference order by tx.created_at desc limit 1) t on true\n        left join public.zynth_strategies st on st.id=nullif(t.metadata->>'strategy_id','')::uuid\n        order by d.created_at desc limit 100\n      ) x\n    ),'[]'::jsonb)\n  ) into result;\n  return result;\nend;\n$$;\n\nrevoke execute on function public.admin_overview() from public, anon;\ngrant execute on function public.admin_overview() to authenticated;\n\ncreate or replace function public.zynth_admin_dashboard()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path='public','pg_temp'\nas $$\ndeclare result jsonb;\nbegin\n  if auth.uid() is null or not exists(select 1 from public.users where id=auth.uid() and role='admin') then\n    raise exception 'ADMIN_AUTHORIZATION_REQUIRED';\n  end if;\n\n  select jsonb_build_object(\n    'investors',coalesce((select count(*) from public.users where role='user'),0),\n    'traders',coalesce((select count(*) from public.users where role='trader'),0),\n    'strategies',coalesce((select count(*) from public.zynth_strategies where status='active'),0),\n    'aumm',coalesce((select sum(current_value) from public.zynth_investments where status='active'),0),\n    'pending_reports',coalesce((select count(*) from public.zynth_daily_reports where status='pending'),0),\n    'settlements_30d',coalesce((select count(*) from public.zynth_settlements where settled_at>now()-interval '30 days'),0),\n    'withdrawals_pending',coalesce((select count(*) from public.withdrawal_requests where status in ('pending','under_review','processing')),0),\n    'pending_deposits',coalesce((select count(*) from public.deposit_requests where status='pending'),0),\n    'deposits_30d',coalesce((select count(*) from public.deposit_requests where status='confirmed' and processed_at>now()-interval '30 days'),0),\n    'pending_report_queue',coalesce((select jsonb_agg(to_jsonb(x) order by x.report_date asc) from (select r.id,r.report_date,r.closing_balance,r.return_pct,s.name strategy_name,u.full_name trader_name from public.zynth_daily_reports r join public.zynth_strategies s on s.id=r.strategy_id join public.users u on u.id=r.trader_id where r.status='pending' order by r.report_date asc limit 20)x),'[]'::jsonb)\n  ) into result;\n  return result;\nend;\n$$;\n\nrevoke execute on function public.zynth_admin_dashboard() from public, anon;\ngrant execute on function public.zynth_admin_dashboard() to authenticated;\n